using System.Text.Json;
using Microsoft.AspNetCore.Mvc;

namespace SecureGateway.Gateway.Extensions;

/// <summary>
/// Writes RFC 9457 problem details for responses generated by the gateway itself, always
/// including the correlation id so that support teams can locate the matching log entries.
/// </summary>
public static class GatewayProblemDetails
{
    public const string ContentType = "application/problem+json";

    private static readonly JsonSerializerOptions SerializerOptions = new(JsonSerializerDefaults.Web);

    public static Task WriteAsync(
        HttpContext context,
        int statusCode,
        string title,
        string detail,
        IDictionary<string, object?>? extensions = null)
    {
        var problem = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            Detail = detail,
            Instance = context.Request.Path,
            Type = $"https://httpstatuses.io/{statusCode}"
        };

        problem.Extensions["correlationId"] = context.GetCorrelationId();

        if (extensions is not null)
        {
            foreach (var (key, value) in extensions)
            {
                problem.Extensions[key] = value;
            }
        }

        context.Response.StatusCode = statusCode;
        return context.Response.WriteAsJsonAsync(problem, SerializerOptions, ContentType, context.RequestAborted);
    }
}
